    def constraint1_fun(x):
        return np.array([x[0] + x[1]])

    def constraint2_fun(x):
        return np.array([x[0] + x[1]])

    nc1 = NonlinearConstraint(constraint1_fun, 0, 1)
    nc2 = NonlinearConstraint(constraint2_fun, 0, 1)

    # Check if hess objects are the same instance
